templates.template:
.ah-gp-icons-container {
	.xf-ahGPIconsContainer()

	a:hover {
		text-decoration: none;
	}

	span {
		cursor: pointer;
	}
}

.ah-gp-icon {
	svg {
		height: @xf-ahGPIconHeight;
		width: @xf-ahGPIconWidth;
	}

	&--playstation svg { fill:  @xf-ahGPColorPlayStation }
	&--xbox svg { fill:  @xf-ahGPColorXbox }
	&--steam svg { fill:  @xf-ahGPColorSteam }
	&--origin svg { fill:  @xf-ahGPColorOrigin }
	&--nintendo svg { fill:  @xf-ahGPColorNintendo }
	&--epicgames svg { fill:  @xf-ahGPColorEpicGames }
	&--battlenet svg { fill:  @xf-ahGPColorBattlenet }
	&--secondlife svg { fill:  @xf-ahGPColorSecondLife }
	&--roblox svg { fill:  @xf-ahGPColorRoblox }
	&--discord svg { fill:  @xf-ahGPColorDiscord }
	&--guilded svg { fill: @xf-ahGPColorGuilded }
	&--twitch svg { fill:  @xf-ahGPColorTwitch }
	&--youtube svg { fill:  @xf-ahGPColorYouTube }
	&--facebook svg { fill:  @xf-ahGPColorFacebook }
	&--twitter svg { fill:  @xf-ahGPColorTwitter }
	&--bluesky svg { fill:  @xf-ahGPColorBlueSky }
	&--reddit svg { fill:  @xf-ahGPColorReddit }
	&--instagram svg { fill:  @xf-ahGPColorInstagram }
	&--tiktok svg { fill:  @xf-ahGPColorTikTok }
	&--telegram svg { fill:  @xf-ahGPColorTelegram }
	&--kick svg { fill:  @xf-ahGPColorKick }
	&--github svg { fill:  @xf-ahGPColorGitHub }
	&--gitlab svg { fill:  @xf-ahGPColorGitLab }
}

.message-user .ah-gp-icons-container {
	.xf-ahGPMessage()
	<xf:if is="property('ahGPIconStyle') == 'spacearound'">
	justify-content: space-around;	
	<xf:elseif is="property('ahGPIconStyle') == 'spacebetween'" />
	justify-content: space-between;
	<xf:elseif is="property('ahGPIconStyle') == 'spaceevenly'" />
	justify-content: space-evenly; 
	<xf:else />
	</xf:if>
}

.memberTooltip .ah-gp-icons-container {
	.xf-ahGPMemberTooltip()
}

<xf:if is="(property('ahGPUnifyColorsCheck'))">
.memberTooltip--withBanner .ah-gp-icon svg { fill: @xf-ahGPUnifiedIconColor !important; }
.memberHeader--withBanner .ah-gp-icon svg { fill: @xf-ahGPUnifiedIconColor !important; }
</xf:if>

.ah-gp-profile {
    position: absolute;
  	top: calc(100% + -170px);  
  	left: 50%;
  	transform: translateX(-10px);                
  	min-width: 425px;
  	opacity: 0 !important;
  	visibility: hidden !important;
  	transition: opacity .3s ease, visibility .3s ease !important;
  	z-index: 1000;            
  	pointer-events: none;      
}

.ah-gp-trigger {
  	position: relative;        
  	overflow: visible;         

  	&:hover .ah-gp-profile {
    	opacity: 1 !important;
    	visibility: visible !important;
    	pointer-events: auto;  
  	}
}

.ah-gp-code-image {
	padding-top: 10px;
}
